package ai_tools

import (
	"context"

	"github.com/azukaar/plurality/src/utils"
)

var HTMLTool = utils.AITool{
	Name:        "HTML Page",
	Description: "Create an HTML page to show the result of a code snippet",
	ToolID:      "html_page",
	Cost:        0,
	ToolRequest: utils.ToolsRequest{
		Type: "function",
		Function: utils.FunctionToolsRequest{
			Name:        "html_page",
			Description: "Create an HTML page to show the result of a code snippet. Use popular libraries like React, ThreeJS, P5.js, Phaser, D3, etc. This tool can be used for any user request that could use some sort of vizualization, or any request for an app, a game, etc...",
			Parameters: &utils.ParameterToolsRequest{
				Type: "object",
				Properties: map[string]utils.PropertyParameterToolsRequest{
					"code": {
						Type:        "string",
						Description: "(Required) The code of the page. It should be a valid HTML page. Use CDN for libraries.",
					},
				},
				Required: []string{"code"},
			},
		},
	},
	LoadingString: "Show Visualization",
	IconURL:       "",
	Exec: func(_ context.Context, args string, _ utils.Conversation) utils.MessageContent {
		// return code
		argsJson := utils.ParseJson(args)

		code := argsJson["code"].(string)

		return utils.NewTextContent(code)
	},
}
